 "바꾸는 중…": "Cambiando…",
 "이 이름은 쓸 수 없어요.": "Este nombre no se puede usar.",
 "태그는 사람 계정만 바꿀 수 있어요.": "Las etiquetas solo las puede cambiar una cuenta de persona.",
 "바꾸지 못했어요. 다시 시도해 주세요.": "No se pudo cambiar. Inténtalo de nuevo.",
 "숫자·태그": "Números · etiquetas",
 "이 계정에는 기억을 밖으로 내보낼 권한이 없어요. 서버 관리자에게 'external:space_bundle' 권한을 받아 주세요.": "Esta cuenta no tiene permiso para sacar recuerdos fuera. Pide al administrador del servidor el permiso «external:space_bundle».",
 "Arkism에서 내보낸 기억 공간 파일인지 확인해 주세요.": "Comprueba que sea un archivo de espacio de recuerdos exportado desde Arkism.",
 "파일이 너무 커요. 8MB까지 가져올 수 있어요.": "El archivo es demasiado grande. Puedes importar hasta 8 MB.",
 "처리하지 못했어요. 연결 상태를 확인하고 다시 시도해 주세요.": "No se pudo completar. Comprueba la conexión e inténtalo de nuevo.",
 "내보낼 파일을 만드는 중…": "Creando el archivo para exportar…",
 "파일 다운로드를 시작했어요. 다른 Arkism의 설정 › 고급에서 가져오세요. 기억 내용이 들어 있으니 안전한 곳에 두세요.": "Ha empezado la descarga del archivo. Impórtalo en otro Arkism desde Ajustes › Avanzado. Contiene tus recuerdos, así que guárdalo en un lugar seguro.",
 "이 파일의 기억을 가져올까요? 바로 저장되지 않고 모두 '확인해 주세요'에 후보로 들어가요.": "¿Quieres importar los recuerdos de este archivo? No se guardan directamente: todos entran como candidatos en «Revisa esto».",
 "가져오는 중…": "Importando…",
 "기억 공간 옮기기": "Mover un espacio de recuerdos",
 "이 공간의 기억을 파일로 내보내거나, 받은 파일을 가져와요. 가져온 기억은 내가 확인해야 저장돼요.": "Exporta a un archivo los recuerdos de este espacio o importa un archivo que hayas recibido. Los recuerdos importados solo se guardan cuando los revisas.",
 "기억 내보내기": "Exportar recuerdos",
 "기억 가져오기": "Importar recuerdos",
