 "기억 뽑을 모델": "Modelo para extraer recuerdos",
 "기억을 뽑을 프로그램이 없어요": "Falta el programa que extrae los recuerdos",
 "프로그램 없음": "Falta el programa",
 "기억을 뽑으려면 로그인이 필요해요": "Para extraer recuerdos hay que iniciar sesión",
 "기억을 뽑는 모델이 답하지 않았어요": "El modelo que extrae recuerdos no respondió",
 "기억을 뽑는 모델의 답을 읽지 못했어요": "No se pudo leer la respuesta del modelo que extrae recuerdos",
 "모델이 정해진 모양으로 답하지 않았어요. 다른 모델을 고르면 나아질 수 있어요.": "El modelo no respondió con el formato esperado. Elegir otro modelo puede ayudar.",
 "답을 못 읽음": "Respuesta ilegible",
 "기억을 뽑는 데 너무 오래 걸렸어요": "Extraer los recuerdos tardó demasiado",
 "다음 분석 때 저절로 다시 해요. 계속되면 더 빠른 모델을 고르세요.": "Se volverá a intentar solo en el próximo análisis. Si sigue pasando, elige un modelo más rápido.",
 "너무 오래 걸림": "Demasiado lento",
 "로그인하기": "Iniciar sesión",
 "다른 모델 고르기": "Elegir otro modelo",
 "에이전트를 다시 연결했어요. 열려 있는 에이전트는 다시 시작하세요.": "Has vuelto a conectar los agentes. Reinicia los agentes que estén abiertos.",
 "다시 연결하지 못했어요. 설정 › 고급 › 진단에서 점검해 보세요.": "No se pudo volver a conectar. Haz una revisión en Ajustes › Avanzado › Diagnóstico.",
 "에이전트 설정 파일을 고치지 못해 대화를 모으지 못해요.": "No se pudieron modificar los archivos de configuración de los agentes, así que no se recopilan las conversaciones.",
 "Claude Code나 Codex를 설치하면 1분 안에 이어져요.": "Instala Claude Code o Codex y se conectará en menos de un minuto.",
 "바꾸기 전 파일은 여기 있어요:": "Los archivos de antes del cambio están aquí:",
 "에이전트 관리": "Gestionar agentes",
 "준비됨": "Listo",
 "에이전트가 처음 보고하면 여기에 보여요.": "Aparecerá aquí cuando tus agentes informen por primera vez.",
 "평소처럼 대화하기": "Conversa como siempre",
 "에이전트와 평소처럼 대화하면, 대화가 끝나고 몇 분 뒤 기억 후보가 여기 와요. 내가 승인한 것만 저장돼요.": "Conversa con tus agentes como siempre. Unos minutos después de terminar una conversación, llegarán aquí candidatos a recuerdo. Solo se guarda lo que tú apruebes.",
 "기존 지침 파일 가져오기": "Importar archivos de instrucciones existentes",
 "에이전트 지침 파일을 살펴보는 중이에요…": "Revisando los archivos de instrucciones de tus agentes…",
 "가져올 지침 파일이 없어요.": "No hay archivos de instrucciones para importar.",
 "바꾸지 못했어요.": "No se pudo cambiar.",
 "PC에 로그인하면 Arkism이 트레이에서 자동으로 켜져요. 그래야 대화를 계속 모아요.": "Cuando inicies sesión en tu PC, Arkism se abrirá solo en la bandeja. Así sigue recopilando las conversaciones.",
 "PC에 로그인해도 Arkism이 켜지지 않아요. 앱이 꺼져 있으면 대화를 모으지 않아요.": "Arkism no se abre al iniciar sesión en tu PC. Si la app está cerrada, no se recopilan las conversaciones.",
 "시작하기": "Empezar",
 "아래가 모두 준비되면 대화에서 기억 후보가 모여요.": "Cuando todo lo de abajo esté listo, se reunirán candidatos a recuerdo de tus conversaciones.",
 "서버에 설치하는 방법": "Cómo instalar en un servidor",
 "이미 켜는 중이에요. 잠시 뒤에 다시 시도하세요.": "Ya se está iniciando. Inténtalo de nuevo en un momento.",
 "이 PC용 Arkism 파일을 찾지 못했어요. 앱을 다시 설치하면 고쳐져요.": "No se encontraron los archivos de Arkism para este PC. Reinstalando la app se arregla.",
 "기억을 저장할 곳을 만들지 못했어요. 저장 폴더에 쓸 수 있는지, 디스크가 꽉 차지 않았는지 확인하세요.": "No se pudo crear el lugar para guardar los recuerdos. Comprueba que se pueda escribir en la carpeta de almacenamiento y que el disco no esté lleno.",
 "기억 저장소를 켜지 못했어요. 앱을 모두 닫았다가 다시 열어 보세요.": "No se pudo iniciar el almacén de recuerdos. Cierra la app por completo y ábrela de nuevo.",
 "Arkism을 켜지 못했어요. 다른 Arkism 창이 열려 있으면 닫고 다시 시도하세요.": "No se pudo iniciar Arkism. Si hay otra ventana de Arkism abierta, ciérrala e inténtalo de nuevo.",
 "이 PC의 접속 열쇠를 확인하지 못했어요.": "No se pudo comprobar la clave de acceso de este PC.",
 "이 PC의 접속 열쇠를 새로 만들지 못했어요.": "No se pudo crear una nueva clave de acceso para este PC.",
 "이 PC의 접속 열쇠가 취소됐어요. 다시 시도하면 새로 만들어요.": "Se revocó la clave de acceso de este PC. Si lo intentas de nuevo, se creará una nueva.",
 "모델 연결 기능을 켜지 못했어요.": "No se pudo activar la conexión con los modelos.",
 "저장 폴더를 만들지 못했어요. 폴더 권한과 남은 디스크를 확인하세요.": "No se pudo crear la carpeta de almacenamiento. Comprueba los permisos de la carpeta y el espacio libre en el disco.",
 "켜는 중에 문제가 생겼어요.": "Hubo un problema al iniciar.",
 "점검에서 문제를 찾지 못했어요. 다시 시도를 눌러 보세요.": "La revisión no encontró ningún problema. Pulsa Reintentar.",
 "자세히 (사용자·포트·인증 방식)": "Más (usuario · puerto · método de acceso)",
 "user@서버주소 또는 ~/.ssh/config의 Host 별칭": "user@dirección-del-servidor o un alias de Host de ~/.ssh/config",
