 "점검하고 고치기": "Revisar y arreglar",
 "기록 폴더 열기": "Abrir carpeta de registros",
 "서버에 Arkism이 설치돼 있어야 해요. 포트는 따로 열지 않아도 돼요. SSH 키나 비밀번호로 접속되면 이 앱이 나머지를 해요.": "Arkism debe estar instalado en el servidor. No hace falta abrir puertos: cuando se pueda entrar por SSH con una clave o contraseña, esta app hace el resto.",
 "서버에 설치하는 방법 ›": "Cómo instalar en un servidor ›",
