 "느릴 때": "Cuando va lento",
 "보통 / 느릴 때": "Normal / cuando va lento",
 "이 서버는 아직 라우팅을 지원하지 않아요. 서버에 모델 라우터가 연결되면 여기서 요청 수·응답 시간·성공률·비용을 볼 수 있어요.": "Este servidor aún no admite el enrutamiento. Cuando se conecte un router de modelos al servidor, podrás ver aquí el número de solicitudes, el tiempo de respuesta, la tasa de éxito y el costo.",
 "이번 달": "Este mes",
 "판정 모델이 고르지 않음": "El modelo evaluador no eligió",
 "직접 고름": "Elegido a mano",
 "에이전트가 직접 쓴 토큰은 Memory·Flow 메뉴의 사용량에서 봐요.": "Los tokens que usa un agente directamente se ven en Uso, dentro de los menús Memory y Flow.",
 "공개 가격으로 셈한 추정": "Estimación según precios públicos",
 "보통 걸린 시간": "Tiempo normal",
 "100건 중 가장 느린 5건이 걸린 시간이에요.": "Es el tiempo que tardaron las 5 solicitudes más lentas de cada 100.",
 "Arkism 라우터를 거친 요청만 세요. 에이전트가 직접 쓴 토큰은 Memory·Flow 메뉴의 사용량에서 봐요.": "Solo cuenta las solicitudes que pasaron por el router de Arkism. Los tokens que usa un agente directamente se ven en Uso, dentro de los menús Memory y Flow.",
