 "글쓰기·번역·요약·이메일 같은 낱말이 든 요청": "Solicitudes con palabras como escribir, traducir, resumir o correo",
 "짧은 질문": "Preguntas cortas",
 "위에 해당하지 않는 짧은 요청(80자 이하)": "Solicitudes cortas (80 caracteres o menos) que no encajan en lo anterior",
 "이 기간에는 라우터를 거친 요청이 없어요": "En este periodo no hubo solicitudes que pasaran por el router",
 "에이전트(Claude Code·Codex·Gemini CLI)를 연결하면 요청이 라우터를 거쳐 알맞은 모델로 가고, 여기에 요청 수·응답 시간·비용이 나와요.": "Si conectas un agente (Claude Code, Codex, Gemini CLI), sus solicitudes pasan por el router y van al modelo adecuado. Aquí verás el número de solicitudes, el tiempo de respuesta y el costo.",
 "에이전트 연결하기": "Conectar un agente",
 "이번 달 비용이 월 예산을 넘었어요": "El costo de este mes superó el presupuesto mensual",
 "1번 모델": "Modelo 1",
