 "AI가 고르지 못했어요.": "La IA no pudo elegir.",
 "이 세션을 찾지 못했어요. 지워졌거나 보관 기간이 지났을 수 있어요.": "No se encontró esta sesión. Puede que se haya borrado o que haya pasado su período de conservación.",
