 "자료 목록을 불러오지 못했어요. 잠시 뒤 다시 불러와요.": "No se pudo cargar la lista de documentos. Se volverá a intentar en un momento.",
 "주제를 불러오지 못해 주제별 보기가 빠졌어요. 지도를 다시 열면 다시 불러와요.": "No se pudieron cargar los temas, así que falta la vista por tema. Vuelve a abrir el mapa para reintentar.",
 "스크립트 목록을 불러오지 못했어요. 다시 열면 다시 불러와요.": "No se pudo cargar la lista de scripts. Ábrelo de nuevo para reintentar.",
