 "넣을 수 있는 전문가를 모두 넣었어요.": "Ya añadiste a todos los expertos posibles.",
 "먼저 전문가를 만들어 주세요.": "Primero crea un experto.",
 "전문가에게 바로 물어봐요": "Pregunta directamente a un experto",
 "전문가 여럿이 정한 순서대로 말하며 하나의 결과를 만들어요. 연결된 채널에 글을 쓰면 회의가 시작돼요.": "Varios expertos hablan en el orden que definas y producen un único resultado. Si escribes en un canal conectado, empieza la reunión.",
