 "연결을 끊고 원래 설정으로 돌려놨어요.": "Se desconectó y se restauró la configuración original.",
 "Codex 설정에 이미 arkism 공급자가 있어요. 직접 지운 뒤 다시 해 주세요.": "La configuración de Codex ya tiene un proveedor arkism. Elimínalo tú mismo y vuelve a intentarlo.",
 "에이전트 설정 파일을 읽지 못했어요.": "No se pudo leer el archivo de configuración del agente.",
 "연결하지 못했어요.": "No se pudo conectar.",
 "이미 연결하는 중이에요.": "Ya se está conectando.",
 "이 PC에서 찾지 못했어요.": "No se encontró en este PC.",
 "연결한 에이전트는 이 PC의 Arkism 중계기로 요청을 보내고, 설정 › 에이전트에서 켠 모델 중에서 자동으로 골라 답해요. 각자 로그인은 그대로 써요.": "Los agentes conectados envían sus solicitudes a la puerta de enlace de Arkism de este PC, que elige automáticamente uno de los modelos activados en Ajustes › Agentes para responder. Cada agente sigue usando su propio inicio de sesión.",
 "기본 모델이 ‘자동’이 돼요. /model에서 다른 모델도 고를 수 있어요.": "El modelo predeterminado pasa a ser ‘Automático’. También puedes elegir otros modelos con /model.",
 "~/.codex/config.toml에 Arkism 공급자를 넣고 모델을 ‘자동’으로 바꿔요.": "Añade un proveedor de Arkism en ~/.codex/config.toml y cambia el modelo a ‘Automático’.",
 "API 키로 로그인한 Gemini CLI만 돼요. Google 로그인은 주소 설정을 무시해요.": "Solo funciona con Gemini CLI que haya iniciado sesión con una clave de API. El inicio de sesión de Google ignora la configuración de la dirección.",
 "판별 모델": "Modelo evaluador",
