 "없으면 비워 두기": "Déjalo vacío si no tienes",
 "Jev를 쓰려면 API 키가 필요해요.": "Para usar Jev necesitas una clave de API.",
 "내 모델로 판별하려면 주소와 모델 이름이 필요해요.": "Para evaluar con tu propio modelo, necesitas la dirección y el nombre del modelo.",
 "주소는 https이거나 이 PC(127.0.0.1)여야 해요.": "La dirección debe ser https o este PC (127.0.0.1).",
 "모델 이름이나 주소를 확인해 주세요.": "Revisa el nombre del modelo o la dirección.",
 "아직 서버 검사가 안 된 스킬이라, 스킬 설명이 얼마나 갖춰졌는지와 가져올 때 검사한 결과로 보여줘요.": "Esta skill aún no se ha revisado en el servidor, así que se muestra según lo completa que está su descripción y el resultado de la revisión al importarla.",
 "Arkism 내장 검사(비밀값·원격 실행·삭제 명령·자격 파일·유출·프롬프트 주입, SKILL.md 구성)가 서버의 스킬 폴더를 검사한 결과예요.": "Es el resultado de la revisión integrada de Arkism sobre la carpeta de la skill en el servidor (secretos, ejecución remota, comandos de borrado, archivos de credenciales, filtración de datos, inyección de prompts y estructura de SKILL.md).",
 "연결하기": "Conectar",
 "비우면 ~/.ssh/config 또는 지금 사용자": "Si lo dejas vacío, se usa ~/.ssh/config o el usuario actual",
 "비우면 22 또는 ~/.ssh/config의 포트": "Si lo dejas vacío, se usa 22 o el puerto de ~/.ssh/config",
 "개인 키 경로. 비우면 ssh-agent 또는 ~/.ssh/config": "Ruta de la clave privada. Si lo dejas vacío, se usa ssh-agent o ~/.ssh/config",
 "Arkism 경로 (선택)": "Ruta de Arkism (opcional)",
 "서버의 arkism 프로그램 전체 경로. 비우면 자동으로 찾아요": "Ruta completa del programa arkism en el servidor. Si lo dejas vacío, se busca automáticamente",
