 "만료 날짜": "Fecha de caducidad",
 "날짜로 정하기": "Elegir fecha",
 "오늘 이후 날짜를 고르세요.": "Elige una fecha posterior a hoy.",
 "만료일 지우기": "Quitar fecha de caducidad",
 "개인정보 지우기": "Borrar datos personales",
 "이 기억과 근거가 된 원본 기록을 영구히 지워요. 같은 원본에서 나온 다른 기억도 함께 지워져요.": "Borra para siempre esta memoria y los registros originales en los que se basa. También se borran otras memorias que provengan del mismo origen.",
 "영구 삭제": "Borrar para siempre",
 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "Escribe lo que quieres borrar, como el nombre de una persona o un correo electrónico. Arkism encuentra todas las memorias y registros originales que lo contengan y los borra para siempre. Antes te mostramos cuántos son.",
 "지울 말 (이름·메일 주소 등)": "Texto que borrar (nombre, correo electrónico, etc.)",
 "예: 홍길동, name@example.com": "Ej.: Juan Pérez, name@example.com",
 "너무 많아 일부만 셌어요. 지운 뒤 다시 찾아보세요.": "Hay demasiados y solo se contaron algunos. Después de borrar, vuelve a buscar.",
 "조금 짧게 입력하세요.": "Escribe algo un poco más corto.",
 "두 글자 이상 입력하세요.": "Escribe al menos dos caracteres.",
 "이 계정은 기억과 원본 기록을 찾을 수 없어요.": "Esta cuenta no puede buscar memorias ni registros originales.",
 "찾지 못했어요. 연결을 확인하고 다시 시도하세요.": "No se pudo buscar. Revisa la conexión y vuelve a intentarlo.",
 "입력한 말이 달라 지우지 않았어요.": "El texto escrito no coincide, así que no se borró nada.",
 "user@서버주소": "user@dirección-del-servidor",
 "연결하는 중…": "Conectando…",
 "연결 끊김": "Conexión perdida",
 "다른 서버에 연결": "Conectar a otro servidor",
 "서버 연결은 Arkism 앱에서만 돼요.": "La conexión a un servidor solo funciona en la aplicación Arkism.",
 "접속 토큰": "Token de acceso",
 "서버 관리자에게 받은 Arkism 접속 토큰. 이 탭을 닫으면 지워져요": "El token de acceso de Arkism que te dio el administrador del servidor. Se borra al cerrar esta pestaña",
 "자세히 (워크스페이스·프로젝트)": "Detalles (espacio de trabajo · proyecto)",
 "워크스페이스": "Espacio de trabajo",
 "비우면 default": "Si lo dejas vacío, se usa default",
 "접속 토큰을 넣어 주세요. 띄어쓰기 없이 한 줄이어야 해요.": "Introduce el token de acceso. Debe ser una sola línea y sin espacios.",
 "Arkism 서버에 로그인": "Iniciar sesión en el servidor de Arkism",
 "서버 관리자에게 받은 접속 토큰을 붙여 넣으세요. 토큰은 이 브라우저 탭에만 두고, 탭을 닫으면 지워져요.": "Pega el token de acceso que te dio el administrador del servidor. El token solo se guarda en esta pestaña del navegador y se borra al cerrarla.",
 "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "Revisa la dirección. Escríbela como user@servidor o user@servidor:puerto.",
 "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "No se encontró el programa ssh en este PC. Instala OpenSSH (o Git for Windows).",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "Se rechazó el inicio de sesión SSH. Comprueba que ‘ssh dirección’ funcione en este PC sin contraseña (con una clave SSH).",
 "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "No se pudo llegar al servidor. Revisa la dirección, el puerto y tu conexión de red.",
 "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "Se inició sesión en el servidor, pero Arkism no está instalado allí.",
 "서버의 Arkism이 오래돼서 이 연결 방식을 몰라요. 서버의 Arkism을 업데이트해 주세요.": "El Arkism del servidor es demasiado antiguo y no reconoce este tipo de conexión. Actualiza Arkism en el servidor.",
 "연결은 됐지만 서버의 Arkism을 열지 못했어요. 서버에서 Arkism이 켜져 있는지 확인하세요.": "Se conectó, pero no se pudo abrir el Arkism del servidor. Comprueba que Arkism esté en ejecución en el servidor.",
 "진단": "Diagnóstico",
 "문제": "Problema",
 "고치는 중…": "Arreglando…",
 "점검하는 중…": "Comprobando…",
 "점검하지 못했어요.": "No se pudo hacer la comprobación.",
 "점검": "Comprobar",
 "예: 회사 고객 이름은 기억하지 마. 배포·테스트 규칙은 꼭 기억해.": "Ej.: No recuerdes los nombres de los clientes de la empresa. Recuerda siempre las reglas de despliegue y de pruebas.",
 "기억할 것에 대한 메모": "Nota sobre lo que debe recordar",
