 "무엇을 기억할지 메모": "Nota sobre qué recordar",
 "Arkism이 기억을 고를 때 참고해요. 비밀값·개인정보 규칙보다 앞서지는 않아요.": "Arkism la consulta al elegir qué recordar. No tiene prioridad sobre las reglas de claves secretas y datos personales.",
