 "되돌아가는 선이에요. 최대 2번까지 다시 돌아요. 선을 눌러 횟수와 갈래 이름을 바꿀 수 있어요.": "Es una línea que vuelve atrás. Se repite hasta 2 veces. Haz clic en la línea para cambiar el número de repeticiones y el nombre de la rama.",
 "노드마다": "En cada nodo",
