 "워크플로우 설정": "Ajustes del flujo de trabajo",
 "노드 설정": "Ajustes del nodo",
 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Haz clic en un nodo para editarlo aquí. Arrastra el punto de salida para conectarlo con el siguiente nodo; si lo conectas con un nodo anterior, se crea una línea que vuelve atrás. Haz clic en una línea para abrir sus ajustes. Usa la rueda para acercar o alejar, y haz clic con la rueda o mantén pulsada la barra espaciadora y arrastra para mover la vista.",
 "노드": "Nodo",
 "되돌아가는 선": "Línea que vuelve atrás",
 "고르세요": "Elige",
 "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "Si la salida es {\"ok\": true/false, …}, se divide en ramas de éxito y fallo. La primera vez tarda 1–2 segundos en compilarse y debe terminar en menos de 30 segundos. No gasta tokens.",
