 "갈래": "Rama",
 "최대 몇 번 되돌아갈까요": "Máximo de retrocesos",
 "넘으면 실행을 멈추고 이유를 남겨요. 성공한 노드 결과는 그대로 두고 대상부터 다시 돌아요.": "Si se supera, la ejecución se detiene y deja el motivo. Los resultados de los nodos que salieron bien se conservan y se vuelve a ejecutar desde el destino.",
