 "관계 확인": "Confirmar relación",
 "관계를 확인했어요.": "Se confirmó la relación.",
 "확인 조건을 충족했어요. 이 관계를 확인하려면 ‘관계 확인’을 눌러 주세요.": "Se cumplen las condiciones. Para confirmar esta relación, pulsa ‘Confirmar relación’.",
 "확인되지 않았어요. 목록을 다시 조회해 주세요.": "No se confirmó. Vuelve a cargar la lista.",
 "처리 결과를 확인하지 못했어요. 권한이나 근거가 바뀌었을 수 있으니 목록을 다시 조회해 주세요.": "No se pudo comprobar el resultado. Puede que hayan cambiado los permisos o la evidencia, así que vuelve a cargar la lista.",
 "내용을 확인한 뒤 기존 화면에서 검토하거나 고칠 수 있어요.": "Tras revisar el contenido, puedes revisarlo o corregirlo en la pantalla existente.",
 "여러 관측을 묶은 교훈이에요. 대표 후보 하나만 검토하며, 묶음 전체를 승인하지 않아요.": "Es una lección que agrupa varias observaciones. Solo se revisa un candidato representativo; no se aprueba el grupo completo.",
 "기억 확인·정정": "Comprobar y corregir memoria",
 "후보 검토": "Revisar candidato",
 "대표 후보 검토": "Revisar candidato representativo",
 "기록을 열 수 없어요. 권한이나 내용이 바뀌었을 수 있으니 목록을 다시 조회해 주세요.": "No se puede abrir el registro. Puede que hayan cambiado los permisos o el contenido, así que vuelve a cargar la lista.",
 "같은 작업에서 이어서 사용한 스킬의 관측이에요. 인과관계나 실행 허가를 뜻하지 않아요.": "Es una observación de skills usadas una tras otra en la misma tarea. No implica causalidad ni permiso para ejecutar.",
 "사용자에 대한 관측과 추정이에요. 현재 지시나 실행 승인을 뜻하지 않아요.": "Son observaciones e inferencias sobre el usuario. No son instrucciones actuales ni una aprobación para ejecutar.",
 "작업에서 얻은 해석이에요. 사실이나 실행 승인을 뜻하지 않아요.": "Es una interpretación obtenida del trabajo. No es un hecho ni una aprobación para ejecutar.",
