 "설치를 요청했어요. 서버가 1분 안에 설치해요…": "Pedimos la instalación. El servidor la hará en menos de un minuto…",
 "설치 결과를 아직 받지 못했어요. 잠시 뒤 스킬 목록을 확인해 주세요.": "Aún no recibimos el resultado de la instalación. Revisa la lista de skills dentro de un momento.",
 "프로그램": "Programa",
 "자주 쓰는 서버": "Servidores populares",
 "상태 아이콘 색: 초록 정상 · 주황 확인 필요 · 빨강 연결 문제·멈춤": "Colores del estado: verde, todo bien · naranja, hay que revisar · rojo, problema de conexión o detenido",
 "개선안 만들기 → 기존 버전과 비교 → 검토·승인 → 실제 작업에 시험 적용 순서로 진행해요.": "El proceso es: crear una mejora → compararla con la versión actual → revisar y aprobar → probarla en trabajo real.",
 "저장소 주소를 넣으면 안에 있는 스킬을 보여 줘요. 받은 파일은 실행하지 않아요.": "Escribe la dirección de un repositorio para ver los skills que contiene. Los archivos descargados no se ejecutan.",
 "에이전트가 일할 때 꺼내 쓰는 작업 방법이에요.": "Son métodos de trabajo que los agentes usan mientras trabajan.",
 "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Conjuntos de colores, fuentes y reglas para apps, correo, web y documentos. Elige uno para ver los detalles a la derecha.",
 "슬라이드 프롬프트": "Prompts de diapositivas",
 "변수 값을 채우고 바로 만들거나, ComfyUI 워크플로우로 보내요.": "Rellena las variables y créalo al instante, o envíalo a un flujo de trabajo de ComfyUI.",
 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Reúne prompts de diapositivas para presentaciones e informes, junto con los scripts que las crean. Elige una tarjeta para editarla a la derecha y crearla al instante.",
 "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Reúne tus prompts de imagen favoritos con imágenes de ejemplo. Filtra por modelo y categoría.",
 "플러그인은 스킬 + MCP + 명령을 한 번에 설치하는 묶음이에요.": "Un plugin es un paquete que instala skills, MCP y comandos de una sola vez.",
 "에이전트가 쓰는 외부 도구 서버예요. 플러그인은 스킬·MCP를 묶어서 한 번에 설치해요.": "Son servidores de herramientas externas que usan los agentes. Los plugins agrupan skills y MCP para instalarlos de una vez.",
