 "이 기간에 센 결정이 없어요.": "No hay decisiones contadas en este periodo.",
 "사람과 AI가 내린 결정을 종류·이유별로 세요. 감사 기록이 지워져도 수는 남아요.": "Cuenta las decisiones tomadas por personas y por la IA, según su tipo y su motivo. Los recuentos se conservan aunque se borre el registro de auditoría.",
