 "서버 Arkism이 연결 정보를 알려 줘요": "Arkism en el servidor te da los datos de conexión",
 "SSH 터널로 이 앱과 이어요": "Un túnel SSH lo une con esta app",
 "OpenSSH(또는 Git for Windows)가 이 PC에 있어야 해요.": "Este PC necesita OpenSSH (o Git for Windows).",
 "이름·모델·프롬프트를 적어 주세요. 제외할 것이나 스크립트는 오른쪽에서 더할 수 있어요. {변수}처럼 중괄호로 쓰면 변수가 돼요.": "Escribe un nombre, un modelo y un prompt. Puedes añadir exclusiones o scripts a la derecha. Si escribes algo entre llaves, como {variable}, se convierte en una variable.",
 "AI로 이름 짓기": "Poner nombre con IA",
 "파일을 고르거나 이미지를 붙여 넣어요. 저장할 때 512KB 이하 WebP로 줄여요.": "Elige un archivo o pega una imagen. Al guardar, se reduce a WebP de 512KB o menos.",
 "추가 설정": "Más ajustes",
 "비워 두면 모델 기본값으로 만들어요.": "Si lo dejas en blanco, se usan los valores predeterminados del modelo.",
