 "기본 정보": "Información básica",
 "갤러리 카드에 보이는 이름과 설명이에요. 제품과 목적이 같은 것끼리 묶여요.": "Son el nombre y la descripción que se ven en la tarjeta de la galería. Los que tienen el mismo producto y propósito se agrupan.",
 "색과 글꼴": "Colores y fuentes",
 "색은 \"이름 #값\"을 한 줄에 하나씩 적어요.": "Escribe los colores como \"nombre #valor\", uno por línea.",
 "이 디자인 시스템으로 화면을 만들 때 AI가 지킬 규칙이에요.": "Son las reglas que la IA seguirá al crear pantallas con este sistema de diseño.",
 "다른 곳에서 수정됐으면 최신 내용을 확인한 뒤 다시 저장하세요.": "Si se editó en otro lugar, revisa el contenido más reciente y vuelve a guardar.",
 "영역 메뉴": "Menú del área",
 "연결 방법": "Cómo conectar",
 "Arkism 서버를 새 버전으로 올리면 디자인 시스템을 저장할 수 있어요.": "Actualiza el servidor de Arkism a una versión nueva para poder guardar sistemas de diseño.",
