 "넣을 수 있는 승인된 자료가 없어요.": "No hay material aprobado que se pueda añadir.",
 "항상 넣는 자료": "Material que siempre se incluye",
 "+ 자료 넣기": "+ Añadir material",
 "자료": "Material",
 "아직 없어요. 늘 알아야 하는 결정·스킬·문서를 넣어 두면, 부를 때마다 검색보다 먼저 들어가요.": "Aún no hay nada. Añade decisiones, skills o documentos que siempre deba conocer; se incluyen antes que la búsqueda cada vez que lo llames.",
 "전체=다 넣기 · 요약=줄여서 넣기 · 참조=제목만 넣고 필요할 때 읽기 · 고정=그 버전만, 최신=바뀌면 따라가기": "Completo = se añade todo · Resumen = versión reducida · Referencia = solo el título, se lee cuando hace falta · Fijada = solo esa versión · Última = sigue los cambios",
 "나중에": "Más tarde",
 "설정됨": "Configurado",
 "토큰 파일이 깨졌거나 다른 사용자도 읽을 수 있게 열려 있어요. 다시 만들면 고쳐져요.": "El archivo del token está dañado o puede leerlo otro usuario. Si lo vuelves a crear, se arregla.",
 "모델 중계기": "Intermediario de modelos",
 "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "¿Quieres volver a crear el token del intermediario? El nuevo token se guardará en la configuración de los agentes.",
 "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Se creó un token nuevo y se guardó en la configuración de los agentes. Cuando reinicies el intermediario, el token anterior dejará de funcionar.",
 "새 토큰을 만들었어요. 에이전트 설정에는 못 넣었어요 — 진단에서 고치기를 눌러 주세요.": "Se creó un token nuevo, pero no se pudo guardar en la configuración de los agentes. Pulsa Arreglar en Diagnóstico.",
 "토큰을 만들지 못했어요.": "No se pudo crear el token.",
