 "route_skills가 고른 스킬과 판정기예요. 규칙은 판정 모델 없이 검색 1위를 고른 것이고, 확신 낮음은 판정기가 고르지 않은 것이에요.": "Son las skills que eligió route_skills y el juez que las eligió. Reglas significa que se tomó el primer resultado de la búsqueda sin modelo juez; poca seguridad significa que el juez no eligió ninguna.",
