 "부속 호출은 Claude Code가 제목·요약·대화 압축 같은 일로 따로 보내는 호출이에요. 비용은 공개 가격으로 셈한 추정이에요.": "Las llamadas secundarias son las que Claude Code envía aparte para cosas como títulos, resúmenes o compactar la conversación. El costo es una estimación calculada con los precios públicos.",
