 "주제 요약": "Resúmenes de temas",
 "새로 들어온 기억이 이미 있는 기억과 비슷해요. AI 제안을 보고 저장할지, 합칠지, 건너뛸지 골라 주세요.": "Los recuerdos nuevos se parecen a otros que ya tienes. Mira la sugerencia de la IA y elige si guardar, fusionar u omitir.",
 "비슷한 기억을 주제로 묶고 AI가 요약해요. 요약이 바뀌면 바로 쓰지 않고 먼저 확인을 받아요.": "Los recuerdos parecidos se agrupan por temas y la IA los resume. Si un resumen cambia, no se usa de inmediato: primero te pide confirmación.",
