 "아직 주제 요약이 없어요. 승인된 기억이 쌓이면 밤사이 제안돼요.": "Aún no hay resúmenes de temas. Cuando se acumulen recuerdos aprobados, se sugerirán durante la noche.",
 "요약을 불러오지 못했어요. 새로고침하면 다시 불러와요.": "No se pudieron cargar los resúmenes. Actualiza para intentarlo de nuevo.",
 "여기에 표시할 요약이 없어요.": "No hay resúmenes que mostrar aquí.",
 "· 최대 개수에 닿아서 합치기 제안이 나올 수 있어요": "· Se llegó al máximo, así que pueden aparecer sugerencias de fusión",
 "나에 대한 요약": "Resumen sobre mí",
 "바탕 기억이 바뀌거나 지워져 쓸 수 없어요. 다음 실행 때 다시 제안돼요.": "Sus recuerdos de origen cambiaron o se borraron, así que no se puede usar. Se volverá a sugerir en la próxima ejecución.",
 "아직 쓰는 요약은 없어요. 후보를 확인해 주세요.": "Aún no hay ningún resumen en uso. Revisa el borrador.",
 "아직 요약이 없어요. 나에 대한 기억이 승인되면 제안돼요.": "Aún no hay resumen. Se sugerirá cuando se aprueben recuerdos sobre ti.",
 "주제를 고르세요": "Elige un tema",
 "비슷한 기억을 묶은 요약이에요. 사실이나 지시가 아니라 참고 자료로 쓰여요.": "Es un resumen de recuerdos parecidos. Se usa como material de referencia, no como un hecho ni una instrucción.",
 "지금 요약": "Resumen actual",
 "묶인 기억": "Recuerdos agrupados",
 "질문이 이 주제와 맞을 때": "Cuando una pregunta coincide con este tema",
 "모든 에이전트 · 참고 자료로": "Todos los agentes · como referencia",
 "승인된 기억으로 AI가 새 주제를 묶었어요. 이 요약을 쓸까요?": "La IA agrupó recuerdos aprobados en un tema nuevo. ¿Quieres usar este resumen?",
 "비슷한 두 요약을 하나로 합치자는 후보예요. 합치면 두 요약은 이전 버전으로 남아요.": "Es un borrador que fusiona dos resúmenes parecidos en uno. Si los fusionas, ambos quedan como versiones anteriores.",
 "AI가 요약을 고쳤어요. 이 후보로 바꿀까요?": "La IA corrigió el resumen. ¿Quieres cambiar a este borrador?",
 "모아보기 · 나에 대한 요약": "Agrupar · Sobre mí",
 "승인하면 새 세션 시작 때 에이전트에게 참고 자료로 전달돼요(지시가 아님).": "Al aprobarlo, los agentes lo reciben como material de referencia cuando empieza una sesión nueva (no como una instrucción).",
 "AI가 요약 후보를 만들었어요. 바꿀까요?": "La IA preparó un borrador de resumen. ¿Quieres cambiarlo?",
