 "다음 야간 실행 때 새 후보로 나와요.": "Aparecerá como borrador nuevo en la próxima ejecución nocturna.",
 "이 계정은 요약을 다시 만들 수 없어요.": "Esta cuenta no puede volver a generar resúmenes.",
