 "관측에서 실패": "Falló en la observación",
 "사용자 평가 또는 자동 검사에 실패 결과가 있어요. 근거와 내용을 확인해 주세요.": "Hay un resultado fallido en una valoración de usuario o una comprobación automática. Revisa la evidencia y el contenido.",
