 "미정산 예약": "Reservas sin liquidar",
 "사용 확정액과 미정산 예약을 함께 계산해요. 실제 청구 금액과 다를 수 있어요.": "Se calcula sumando el gasto confirmado y las reservas sin liquidar. Puede diferir de la factura real.",
 "오늘 목표를 넘었어요. 목표 초과만으로 처리를 차단하지 않으며 월 예산과 별도 설정한 상한은 계속 적용해요.": "Superaste el objetivo de hoy. Superar el objetivo por sí solo no bloquea el procesamiento; el presupuesto mensual y cualquier límite que hayas configurado siguen vigentes.",
 "오늘 목표는 지출 추이를 보는 기준이에요. 월 예산과 별도 설정한 상한은 계속 적용해요.": "El objetivo de hoy es una referencia para seguir el ritmo del gasto. El presupuesto mensual y cualquier límite que hayas configurado siguen vigentes.",
