 "질문할 때 찾아 넣은 기억의 문구가 답에 보였는지만 세요. 실제 활용 여부는 측정하지 않았고, 읽지 못한 대화 수는 이 통계에서 알 수 없어요.": "Solo cuenta si las frases de los recuerdos encontrados al preguntar aparecieron en la respuesta. No se mide si realmente se usaron, y esta estadística no incluye el número de conversaciones que no se pudieron leer.",
