 "재검토 예정일이 지났어요. 내용이 아직 맞는지 직접 확인해 주세요.": "Ya pasó la fecha de revisión. Comprueba tú mismo si el contenido sigue siendo correcto.",
 "최근 30일 동안 검색으로 전달된 기록이 없어요. 실제 활용 여부와 내용의 필요성은 따로 확인해 주세요.": "En los últimos 30 días no se entregó por búsqueda. Comprueba aparte si realmente se usó y si el contenido sigue siendo necesario.",
 "기억 관리": "Gestión de recuerdos",
