 "이 세션을 지울까요?": "¿Eliminar esta sesión?",
 "세션과 보관된 대화가 지워지고 되돌릴 수 없어요. 에이전트의 원래 파일은 그대로 남고, 이 대화를 출처로 둔 기억은 내용은 남고 출처 연결만 사라져요.": "La sesión y la conversación archivada se eliminarán y no se podrán recuperar. Los archivos originales del agente se conservan, y los recuerdos que tienen esta conversación como origen mantienen su contenido, pero pierden el vínculo con el origen.",
 "불러온 횟수": "Veces recuperado",
 "끝나면 알려줌을 고르면 n8n이 callback_url로 결과를 돌려줄 때까지 멈춰요. 서버에 공개 주소가 있어야 해요.": "Si eliges «avisar al terminar», la ejecución se detiene hasta que n8n devuelva el resultado a callback_url. El servidor debe tener una dirección pública.",
