 "검색 결과": "Resultados de búsqueda",
 "실행할 때 AI가 일을 몇 개로 나눌지 정하고, 워커 결과를 이 노드가 합쳐요.": "Al ejecutarse, la IA decide en cuántas partes dividir el trabajo, y este nodo une los resultados de los trabajadores.",
 "토큰이 없어 모델 중계기를 쓸 수 없어요. 다시 만들면 에이전트 설정에 바로 넣어요.": "No hay token, así que no se puede usar el relé de modelos. Si lo creas de nuevo, se añade enseguida a la configuración del agente.",
 "지금은 환경 변수에 넣은 토큰을 써요.": "Ahora se usa el token de una variable de entorno.",
 "중계기 토큰이 없어요. Claude Code·Codex 요청이 라우팅되지 않아요.": "No hay token del relé. Las solicitudes de Claude Code y Codex no se enrutan.",
 "중계기 토큰 파일에 문제가 있어요. Claude Code·Codex 요청이 라우팅되지 않아요.": "El archivo del token del relé tiene un problema. Las solicitudes de Claude Code y Codex no se enrutan.",
 "대화 수집과 앱 시작을 정해요.": "Define la captura de conversaciones y el inicio de la app.",
 "앱 버전과 Arkism이 기억을 다루는 규칙이에요.": "La versión de la app y las reglas con las que Arkism trata los recuerdos.",
 "이 PC의 Arkism을 쓸지, 서버의 Arkism에 이을지 정해요.": "Elige si usar Arkism en este PC o conectarte al Arkism de un servidor.",
 "바꾸면 바로 적용돼요.": "Los cambios se aplican al instante.",
 "스킬과 대화를 읽어 올 에이전트를 정해요.": "Elige los agentes de los que se leen habilidades y conversaciones.",
 "AI 노드가 맡을 역할과 말투예요.": "El rol y el tono que adopta un nodo de IA.",
 "백업·진단·데이터 지우기처럼 자주 바꾸지 않는 설정이에요.": "Ajustes que no cambias a menudo, como copia de seguridad, diagnóstico y borrado de datos.",
 "Arkism이 정한 규칙이라 바꿀 수 없어요.": "Son reglas de Arkism y no se pueden cambiar.",
 "말투·보고 방식·작업 절차처럼 늘 지킬 것": "Lo que siempre se debe cumplir, como el tono, la forma de informar y los pasos de trabajo",
 "질문과 관련 있을 때만 넣어요": "Se incluye solo cuando es relevante para la pregunta",
 "저장소마다 달라요. 미리보기에서 저장소를 골라 보세요.": "Es distinto en cada repositorio. Elige uno en la vista previa.",
 "저장한 기억은 참고 자료로만 쓰고, 지시로 따르지 않아요.": "Los recuerdos guardados se usan solo como referencia, nunca como instrucciones.",
 "내가 승인해야 쓰여요": "Se usa solo si tú lo apruebas",
 "붙여 넣은 글이나 웹 문서에 섞인 지시": "Instrucciones mezcladas en textos pegados o documentos web",
 "답에 안 드러난 기억 모으기": "Reunir recuerdos que no aparecen en las respuestas",
 "7일 동안 3번 넘게 넣었는데 답과 겹치지 않으면 검토 목록에 모아요": "Si se incluyó más de 3 veces en 7 días y nunca coincidió con una respuesta, pasa a la lista de revisión",
 "창 없이 트레이에서 시작해 대화를 계속 저장해요.": "Se inicia en la bandeja sin ventana y sigue guardando las conversaciones.",
 "서버가 아직 에이전트 목록을 보내지 않았어요. 잠시 뒤 다시 열어 보세요.": "El servidor aún no ha enviado la lista de agentes. Vuelve a abrir esto en un momento.",
 "여러 에이전트가 함께 읽는 스킬 폴더예요. 한 번 넣으면 모두 써요.": "Es una carpeta de habilidades que leen varios agentes. Añade una habilidad una vez y todos la usan.",
