 "3시간마다 교훈을 정리하고 검토할 기억을 골라요.": "Cada 3 horas resume las lecciones y elige recuerdos para revisar.",
 "비워 두면 기본 위치를 써요": "Déjalo vacío para usar la ubicación predeterminada",
 "이 PC에서 Arkism을 실행해요. 인터넷 없이도 돼요.": "Ejecuta Arkism en este PC. Funciona sin internet.",
 "서버의 Arkism을 SSH로 이어요. 서버에서 따로 할 일은 없어요.": "Conecta con el Arkism de un servidor por SSH. No hay que hacer nada en el servidor.",
 "이미지 프롬프트의 ‘ComfyUI에서 열기’가 여는 주소예요.": "Es la dirección que abre «Abrir en ComfyUI» desde los prompts de imagen.",
 "화면·정렬·분류 설정을 파일로 옮겨요.": "Traslada por archivo los ajustes de vista, orden y categorías.",
 "‘유지’한 기억과 정리 설정을 옮겨요. 같은 계정에서만 가져올 수 있어요.": "Traslada los recuerdos marcados como «Mantener» y los ajustes de limpieza. Solo se puede importar en la misma cuenta.",
