 "서버에 SSH로 연결": "Conectar a un servidor por SSH",
 "이 PC에서 Arkism을 실행해요. 인터넷 없이도 되고, 기억은 이 PC에만 저장돼요.": "Ejecuta Arkism en este PC. Funciona sin internet y las memorias se guardan solo en este PC.",
 "서버에서 돌고 있는 Arkism을 SSH로 이어요. 여러 PC가 같은 기억을 써요.": "Se conecta por SSH al Arkism que se ejecuta en tu servidor. Varios PC comparten las mismas memorias.",
 "Arkism을 어디서 쓸까요?": "¿Dónde quieres usar Arkism?",
 "처음 한 번만 고르면 돼요. 나중에 설정 › 연결에서 바꿀 수 있어요.": "Solo tienes que elegir una vez. Después puedes cambiarlo en Ajustes › Conexión.",
 "저장 위치": "Ubicación de almacenamiento",
 "사용자 지정": "Personalizada",
 "기억·설정·토큰이 저장되는 폴더예요. 바꿔도 지금 데이터는 옮기지 않아요.": "Es la carpeta donde se guardan las memorias, los ajustes y los tokens. Si la cambias, los datos actuales no se mueven.",
 "폴더 경로": "Ruta de la carpeta",
 "빈 폴더의 전체 경로": "Ruta completa de una carpeta vacía",
 "기본 위치에 있던 데이터는 그대로 남아요.": "Los datos de la ubicación predeterminada se quedan donde están.",
 "폴더 경로를 넣어 주세요.": "Escribe la ruta de una carpeta.",
 "C:\\ 나 /로 시작하는 전체 경로를 넣어 주세요.": "Escribe una ruta completa que empiece por C:\\ o /.",
 "파일이 아니라 폴더 경로를 넣어 주세요.": "Escribe la ruta de una carpeta, no de un archivo.",
 "빈 폴더나 Arkism 데이터 폴더만 쓸 수 있어요.": "Solo se puede usar una carpeta vacía o una carpeta de datos de Arkism.",
 "이 폴더를 읽을 수 없어요.": "No se puede leer esta carpeta.",
 "이 폴더에 쓸 수 없어요. 권한을 확인해 주세요.": "No se puede escribir en esta carpeta. Revisa los permisos.",
 "저장 위치를 바꿨어요.": "Se cambió la ubicación de almacenamiento.",
 "앱을 다시 열면 새 위치에서 시작해요.": "Arkism empezará en la nueva ubicación la próxima vez que abras la app.",
 "저장 위치를 읽지 못했어요.": "No se pudo leer la ubicación de almacenamiento.",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요. 키가 없으면 인증 방식을 비밀번호로 바꾸세요.": "Se rechazó el inicio de sesión SSH. Comprueba que ‘ssh dirección’ funcione en este PC sin contraseña (con una clave SSH). Si no tienes clave, cambia el método de autenticación a contraseña.",
 "비밀번호 로그인이 거부됐어요. 비밀번호를 확인하세요. 서버가 비밀번호 로그인을 막아 두었으면 SSH 키가 필요해요.": "Se rechazó el inicio de sesión con contraseña. Revisa la contraseña. Si el servidor bloquea el acceso con contraseña, necesitas una clave SSH.",
 "비밀번호 로그인이 거부됐어요": "Se rechazó el inicio de sesión con contraseña",
 "비밀번호를 넣어 주세요.": "Escribe la contraseña.",
 "인증 방식": "Método de autenticación",
 "SSH 키": "Clave SSH",
 "비밀번호": "Contraseña",
 "연결되면 이 PC의 키체인(자격 증명 관리자)에 저장해 다시 묻지 않아요. 비워 두면 저장된 비밀번호를 써요": "Al conectarte, se guarda en el llavero de este PC (Administrador de credenciales) y no se vuelve a pedir. Si lo dejas vacío, se usa la contraseña guardada",
 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "Las pantallas de Git y Habilidades del servidor usan esta conexión. La captura de memoria de los agentes solo llega al servidor con una clave SSH.",
 "SSH 키 또는 ssh-agent로 로그인해요": "Inicia sesión con una clave SSH o ssh-agent",
 "저장된 비밀번호가 없어요. 비밀번호를 넣고 연결하세요.": "No hay contraseña guardada. Escribe la contraseña y conéctate.",
 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "Se accede con una clave SSH o una contraseña. La contraseña se guarda en el llavero de este PC para no pedirla de nuevo, y al pulsar Desconectar se borra la del servidor conectado.",
 "이 PC의 터미널에서 아래 명령으로 같은 비밀번호로 접속되는지 먼저 확인하세요.": "Primero comprueba en una terminal de este PC que el comando de abajo permite conectarse con la misma contraseña.",
