 "이 서버에 설치된 검사 엔진이 없어요. 기본 검사만 돌아요.": "Este servidor no tiene ningún motor de revisión instalado. Solo se ejecuta la revisión básica.",
 "이 서버가 돌릴 수 있는 임베딩은 이것 하나예요. 바꾸려면 서버 설정을 바꾸고 기억을 다시 색인해야 해요.": "Este es el único embedding que puede ejecutar este servidor. Para cambiarlo, tienes que cambiar el ajuste del servidor y volver a indexar las memorias.",
 "서버에 연결해 쓰는 동안에는 서버가 정한 폴더 위치를 써요.": "Mientras estés conectado a un servidor, se usan las ubicaciones de carpetas que defina el servidor.",
 "아직 확인 안 됨": "Aún sin confirmar",
 "임베딩을 바꿀까요?\n저장하면 기억을 모두 다시 색인해요. 기억이 많으면 시간이 걸려요.": "¿Quieres cambiar el embedding?\nAl guardar, se vuelven a indexar todas las memorias. Si tienes muchas, tardará un poco.",
