 "@이름으로 부른 실행의 최종 결과와 전달 상태": "Resultado final y estado de entrega de las ejecuciones llamadas con @nombre",
 "아직 @이름으로 부른 실행이 없어요.": "Todavía no hay ejecuciones llamadas con @nombre.",
 "회의 결과": "Resultado de la reunión",
 "하위 실행": "Ejecución secundaria",
 "사람의 결정이 필요해요": "Se necesita la decisión de una persona",
 "최신 실행을 다시 열어 주세요.": "Vuelve a abrir la ejecución más reciente.",
 "중단을 요청했어요. 실제 종료 상태를 확인해 주세요.": "Se solicitó la detención. Comprueba el estado final real.",
 "결정을 보냈어요. 실행 상태를 다시 확인해요.": "Se envió la decisión. Se vuelve a comprobar el estado de la ejecución.",
 "보내지 못했어요. 상태가 바뀌었거나 권한이 없을 수 있어요. 다시 열어 확인해 주세요.": "No se pudo enviar. Puede que el estado haya cambiado o que no tengas permiso. Ábrelo de nuevo y revisa.",
 "대화로 전달": "Entrega por conversación",
 "보냈는지 확인되지 않아 자동으로 다시 보내지 않아요. 원래 대화와 저장된 메시지 영수증을 먼저 확인해 주세요.": "No se pudo confirmar si se envió, así que no se reenvía automáticamente. Revisa primero la conversación original y los recibos de los mensajes guardados.",
 "권한이나 대화 상태를 확인해 주세요. 전달을 복구하려고 작업을 다시 실행하지 마세요.": "Revisa los permisos y el estado de la conversación. No vuelvas a ejecutar la tarea para recuperar la entrega.",
 "아직 결론이 없어요.": "Todavía no hay conclusión.",
 "전체 회의 기록": "Historial completo de la reunión",
 "전달 복구": "Recuperar entrega",
 "원래 대화 열기": "Abrir la conversación original",
 "전달 복구 방법": "Método de recuperación de la entrega",
 "복구 방법 선택": "Elegir método de recuperación",
 "미확인 부분부터 다시 보내기": "Reenviar desde la parte sin confirmar",
 "이미 받은 메시지 확인하기": "Confirmar un mensaje ya recibido",
 "다른 대화로 처음부터 보내기": "Enviar todo desde el principio a otra conversación",
 "원래 대화에서 미확인 부분이 전송되지 않았는지 확인해 주세요. 이미 받은 부분을 다시 보내면 중복될 수 있어요.": "Comprueba en la conversación original que la parte sin confirmar no se haya enviado. Si reenvías una parte que ya se recibió, puede duplicarse.",
 "원래 대화에서 현재 미확인 부분을 받은 메시지의 ID를 입력해요. 확인 후 다음 부분부터 이어서 전달해요.": "Escribe el ID del mensaje de la conversación original que recibió la parte sin confirmar actual. Tras confirmarlo, la entrega continúa desde la siguiente parte.",
 "입력한 새 대화에 전체 결과를 처음부터 보내요. 기존 대화와 메시지 영수증은 복구 이력에 남아요.": "Se envía el resultado completo desde el principio a la nueva conversación que indiques. La conversación anterior y los recibos de mensajes quedan en el historial de recuperación.",
 "원래 대화를 확인했고 미확인 부분을 다시 보내는 데 동의해요.": "He revisado la conversación original y acepto reenviar la parte sin confirmar.",
 "입력한 메시지가 현재 미확인 부분의 실제 수신 메시지임을 확인했어요.": "He comprobado que el mensaje indicado es el que realmente recibió la parte sin confirmar actual.",
 "새 목적지와 접근 권한을 확인했고 전체 결과를 보내는 데 동의해요.": "He revisado el nuevo destino y los permisos, y acepto enviar el resultado completo.",
 "사람 계정의 복구 권한이 필요해요. 원래 대화를 확인한 뒤 방법을 선택해 주세요.": "Se necesita el permiso de recuperación de una cuenta de persona. Revisa la conversación original y luego elige un método.",
 "복구 내용 확인": "Confirmar los detalles de la recuperación",
 "확인한 내용으로 복구 요청": "Solicitar la recuperación confirmada",
