 "AI 도움을 누르면 승인할지 버릴지 이유와 함께 추천해요. 고르는 건 사람이에요.": "Al pulsar Ayuda de la IA, te recomienda aprobar o descartar y te explica el motivo. La decisión es tuya.",
 "건넸는데 답에 안 쓰인 기억이에요": "Recuerdos que se entregaron pero no se usaron en una respuesta",
 "아직 맞으면 유지, 틀렸으면 고치기, 필요 없으면 잊기를 눌러 주세요.": "Si sigue siendo correcto, pulsa Mantener; si es incorrecto, Corregir; si no hace falta, Olvidar.",
