 "자주 쓰는 순": "Más usados",
 "요즘 자주 씀": "Muy usado últimamente",
 "한동안 안 씀": "Sin usar desde hace tiempo",
 "뒷받침": "Respalda",
 "같은 대화": "Misma conversación",
 "새로 바뀜": "Reemplazado por uno más nuevo",
 "평가를 불러오지 못했어요.": "No se pudo cargar la evaluación.",
 "확인 기록": "Registro de revisión",
 "지금 기억은 이력으로 가요": "La memoria actual pasa al historial",
 "새로 들어온 내용은 버려요": "El contenido nuevo se descarta",
 "둘 다 기억하지 않아요": "No se recuerda ninguno de los dos",
 "둘 다 기억으로 써요": "Se usan los dos como memoria",
 "어디서 왔는지 불러오지 못했어요. 다시 선택해 주세요.": "No se pudo cargar de dónde viene. Vuelve a seleccionarlo.",
 "남아 있는 대화가 없어요.": "No queda ninguna conversación.",
 "이 대화에서 이렇게 말했어요": "Esto se dijo en esta conversación",
 "남은 내용이 없어요.": "No queda contenido.",
 "대화 원문은 지워졌어요.": "Se borró el texto original de la conversación.",
 "대화 원문은 남아 있지 않아요.": "El texto original de la conversación no se conserva.",
 "위 문장은 저장할 때 남긴 발췌예요. 정확한 말은 대화에서 확인해 주세요.": "La frase de arriba es un extracto guardado al momento de guardar. Para ver las palabras exactas, consulta la conversación.",
 "분류 · 정리하는 중": "Clasificación · Ordenando",
 "쓰는 중인 기억 · 잘 쓰이나 확인 결과": "Memorias en uso · Resultados de la revisión de uso",
 "기존 기억은 이력으로 가요": "La memoria existente pasa al historial",
 "새 후보는 버려요": "El nuevo candidato se descarta",
 "쓰는 범위 · AI 추천이 기본, 정하는 건 사람이에요": "Se aplica a · La sugerencia de la IA es la predeterminada, pero decide una persona",
 "어느 프로젝트인지 몰라 고를 수 없어요": "No se puede elegir porque no se sabe de qué proyecto es",
 "넘길 내용을 찾지 못했어요. 서버를 최신 판으로 올리면 쓸 수 있어요.": "No se encontró contenido para pasar. Si actualizas el servidor a la última versión, podrás usarlo.",
