 "이 에이전트는 이어서 하기 명령을 몰라요.": "Este agente no conoce el comando para continuar.",
 "다른 에이전트로 handoff": "Handoff a otro agente",
 "이어서 하기": "Continuar",
 "이어서 하기 명령을 복사했어요. 터미널에 붙여 넣으세요.": "Copiaste el comando para continuar. Pégalo en una terminal.",
 "handoff ⌄": "Handoff ⌄",
 "잘 쓰이나 확인 보기": "Ver revisión de uso",
 "내용이 낡았거나 너무 넓을 수 있어요. 고치거나 「잘 쓰이나 확인」에서 정리해 보세요.": "Puede estar desactualizada o ser demasiado amplia. Edítala o ordénala en «Revisión de uso».",
