 "처음이라면": "Si es tu primera vez",
 "만들어 둔 전문가가 있으면 노드에서 「전문가 불러오기」로 골라요. 잘 되는 노드는 전문가로 저장해 다시 써요.": "Si ya tienes expertos creados, elige uno con «Cargar experto» en un nodo. Guarda como experto un nodo que funcione bien para reutilizarlo.",
 "노드를 더하려면 아래 「+ 노드 추가」나 출력 점을 끌어요. 회의도 노드 종류에서 골라요.": "Para añadir nodos, usa «+ Añadir nodo» de abajo o arrastra el punto de salida. La reunión también se elige en el tipo de nodo.",
