 "빈 칸이나 형식을 확인해 주세요. @이름은 띄어쓰기 없이 글자·숫자·_·-만 써요. 앞으로 가는 선이 원을 이루면 저장되지 않아요(되돌아가는 선은 횟수를 정해요).": "Revisa si hay campos vacíos o formatos incorrectos. Un @nombre solo admite letras, números, _ y -, sin espacios. Si las líneas que avanzan forman un círculo, no se puede guardar (en las líneas que retroceden se define un número de veces).",
 "주소·토큰 보기": "Ver dirección y token",
