 "켜면 이 앱의 스킬 표에 보여요. 끄면 표에서만 숨기고, 대화 수집은 그대로예요.": "Si lo activas, se muestra en las tablas de skills de esta app. Si lo desactivas, solo se oculta en las tablas; la recopilación de chats sigue igual.",
