 "고급 · 요청 헤더 추가 (사내 게이트웨이 인증)": "Avanzado · Añadir encabezados de solicitud (autenticación del gateway de la empresa)",
 "값은 키처럼 서버에만 저장돼요 · 화면엔 이름만 보여요": "Los valores se guardan solo en el servidor, como las claves · en pantalla solo se ven los nombres",
 "헤더 이름은 영문·숫자·-로 쓰고 값도 넣어 주세요. 키는 API 키 칸에 넣어요.": "Escribe el nombre del encabezado con letras, números y -, y añade también el valor. La clave va en el campo de la clave de API.",
 "개발 빌드": "Compilación de desarrollo",
 "토큰은 Arkism에 암호화해 저장하고, 화면에는 끝 4자리만 보여요. 디스코드 개발자 포털에서 봇을 만들고 Message Content Intent를 켠 뒤 토큰을 넣어 주세요.": "El token se guarda cifrado en Arkism y en pantalla solo se ven los últimos 4 caracteres. Crea un bot en el portal de desarrolladores de Discord, activa Message Content Intent y pega el token.",
 "토큰은 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. @BotFather로 만든 봇을 그룹이나 DM에 먼저 추가해 두세요.": "El token se guarda en Arkism y en pantalla solo se ven los últimos 4 caracteres. Antes, añade a un grupo o a un DM el bot que creaste con @BotFather.",
 "웹훅 주소는 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. 슬랙의 Incoming Webhooks에서 만들어요.": "La dirección del webhook se guarda en Arkism y en pantalla solo se ven los últimos 4 caracteres. Se crea en Incoming Webhooks de Slack.",
 "바꾸려면 팀·전문가 상세의 채널 연결에서 해요.": "Para cambiarlo, hazlo en Conexión de canal dentro de los detalles del equipo o del experto.",
 "아직 답이 없어요. 잠시 뒤 다시 확인해 주세요.": "Aún no hay respuesta. Vuelve a comprobar en un momento.",
 "10분 안에 로그인이 끝나지 않았어요. 다시 눌러 주세요.": "El inicio de sesión no terminó en 10 minutos. Púlsalo de nuevo.",
 "로그인 창을 열지 못했어요. 터미널에서 아래 명령을 실행해 주세요.": "No se pudo abrir la ventana de inicio de sesión. Ejecuta el siguiente comando en una terminal.",
 "로그인은 됐지만 계정을 넣지 못했어요. 다시 눌러 주세요.": "Iniciaste sesión, pero no se pudo añadir la cuenta. Púlsalo de nuevo.",
 "로그인 버튼을 누르면 로그인 창이 열려요. 브라우저에서 로그인을 마치면 여기 바로 보여요.": "Al pulsar el botón de inicio de sesión se abre la ventana de acceso. Cuando termines en el navegador, lo verás aquí enseguida.",
 "로그인 창을 열었어요": "Se abrió la ventana de inicio de sesión",
 "브라우저에서 로그인을 마치면 여기서 바로 알려 줘요. 창을 닫지 마세요.": "Cuando termines de iniciar sesión en el navegador, te avisaremos aquí. No cierres la ventana.",
 "이제 이 계정으로 AI를 쓸 수 있어요.": "Ya puedes usar la IA con esta cuenta.",
 "로그인하지 못했어요. 다시 눌러 주세요.": "No se pudo iniciar sesión. Púlsalo de nuevo.",
