 "로그인한 계정이 없어요. 구독으로 쓰려면 계정을 추가하고, API로 쓰려면 아래 'API 키'에서 키를 넣어요.": "No hay ninguna cuenta con sesión iniciada. Para usar la suscripción, añade una cuenta; para usar la API, añade una clave en 'Claves de API', más abajo.",
 "로그인하거나 API 키를 넣으면 이 모델들을 쓸 수 있어요.": "Inicia sesión o añade una clave de API para usar estos modelos.",
 "아직 받은 모델이 없어요. '목록 새로고침'으로 다시 받아 보세요.": "Aún no hay modelos descargados. Prueba con 'Actualizar lista'.",
 "이 PC의 Arkism이 아직 로그인 상태를 읽는 중이에요. 잠시 뒤 보여요.": "Arkism en este PC todavía está leyendo el estado de inicio de sesión. Aparecerá en un momento.",
